content.content:
  .ag-row {
    @apply border-b border-tertiary;
  }

  .ag-root-wrapper-body {
    @apply h-auto;
  }

  .ag-filter-wrapper {
    .ag-input-field-input.ag-text-field-input,
    .ag-input-field-input.ag-number-field-input,
    .ag-picker-field-wrapper.ag-picker-collapsed,
    .ag-picker-field-wrapper.ag-picker-expanded {
      @include input-field;
    }

    .ag-input-field-input.ag-text-field-input,
    .ag-input-field-input.ag-input-field-input {
      @apply pl-5;
    }

    .ag-filter-apply-panel-button.ag-button {
      @apply base-button;
      &[data-ref='applyFilterButton'] {
        @include button-primary;
      }

      &[data-ref='resetFilterButton'] {
        @include button-secondary;
      }
    }
  }

  @apply overflow-x-auto;
  .ag-header {
    @apply border-b border-tertiary;
    .ag-header-cell.align-right {
      .ag-header-cell-label {
        @apply justify-end;
      }
    }
    .ag-header-viewport,
    .ag-pinned-left-header {
      .ag-floating-filter {
        input {
          @include input-field;
          @apply m-0 p-0 px-2;
          height: 24px !important;
        }
      }
      // A filter row with no input (see EmptyFloatingFilter): drop the empty body so the button
      // centres in the cell instead of hanging off its right edge.
      .ag-floating-filter:has(.ag-grid-filter-button-only) {
        .ag-floating-filter-body {
          @apply hidden;
        }

        .ag-floating-filter-button {
          @apply flex h-full w-full items-center justify-center;
          margin: 0;
        }
      }
    }
  }

  .ag-cell {
    user-select: text;
    @apply flex items-center;
    &.ag-grid-no-border,
    &.ag-cell-focus {
      @apply border-0;
    }

    &.column-divider:not(:last-child) {
      @apply border-0 border-r border-solid border-tertiary;
    }

    &.align-right {
      @apply justify-end;
    }
  }
  .ag-cell.ag-cell-first-right-pinned:not(
      .ag-cell-range-left,
      .ag-cell-range-single-cell,
      .ag-cell-focus:not(.ag-cell-range-selected):focus-within
    ) {
    @apply border-0;
  }
  .ag-error-row {
    @apply bg-error;
    #editable-cell-renderer {
      @apply border-error;
    }
    &.ag-error-border {
      @apply border border-error;
      @apply cursor-pointer;
    }
    &.ag-row-hover:not(.ag-full-width-row):before {
      @apply bg-transparent;
    }
  }
    margin-bottom: 0;

    .tooltip-arrow {
      transform: rotate(180deg);
    }
  }
}

.heat-map-grid {
  // Keep AG Grid's internal horizontal scroll usable. overflow:visible on the header
  // viewport breaks scroll sync and clips trailing test-case columns.
  .ag-theme-balham-dark {
    overflow-x: hidden;
  }

  .ag-header-cell.heat-map-test-case-header {
    padding-left: 0 !important;
    padding-right: 0 !important;

    .ag-header-cell-comp-wrapper {
      height: 100%;
      padding-left: 0;
      padding-right: 0;
    }
  }

  .ag-header-cell {
    border-top: none !important;
    border-left: none !important;
    @apply border-r border-b border-tertiary;
  }

  .ag-cell {
    border-top: none !important;
    border-left: none !important;
    @apply border-r border-b border-tertiary;
    padding: 0 !important;
  }

  // The kit wraps the score renderer in a dropdown trigger (`items-center`) and a
  // content-sized span. With the number hidden, that span collapses to the 1px
  // border, so the bucket color never fills the row.
  .ag-cell > .dial-kit-dropdown {
    align-items: stretch;

    > span {
      display: flex;
      height: 100%;
      min-height: 0;
    }
  }

  .ag-body-horizontal-scroll {
    min-height: 12px;
  }
}

// GridView wraps the grid in height: 100%. Auto height must follow the rows instead,
// otherwise the stability heatmap stays inside a fixed viewport and scrolls.
.heat-map-grid--auto-height {
  > .size-full {
    height: auto;
  }
}

.conversations-grid {
  .ag-header-group-cell {
    @apply border-b border-tertiary pt-1.5;
  }

  .ag-header-group-cell-label {
    @apply items-start justify-start;
  }

  .ag-header-cell {
    @apply py-1.5;
  }

  .ag-cell {
    @apply py-2;
  }
}

