// `@apply` only takes utilities in Tailwind v4, so the shared building blocks are declared as such.
@utility input-disable {
  @apply bg-layer-3 text-secondary;
}

@utility base-button {
  @apply flex flex-row items-center px-3 py-2;
  @apply rounded border border-solid border-transparent text-sm;

  min-width: 38px;
  min-height: 38px;
}

@utility base-button-disable {
  @apply pointer-events-none text-controls-disable bg-controls-disable;
}

// Shared by `.input` and by the AG Grid fields that look like it: `@apply` cannot take a class in Tailwind v4.
@mixin input-field {
  @apply border border-solid border-primary rounded outline-0;
  @apply bg-transparent text-sm truncate;
  @apply px-3 py-2;

  &:not(:placeholder-shown) {
    @apply text-primary;
  }

  &:hover {
    @apply border-hover;
  }

  &:focus,
  &:focus-within {
    @apply border-accent-primary;
  }

  &:disabled {
    @apply bg-layer-3 text-secondary;
  }
}

// Same reason as `input-field`: the grid buttons reuse these through `@include`.
@mixin button-primary {
  @apply base-button bg-controls-accent text-controls-primary;

  &:hover,
  &:focus {
    @apply bg-controls-accent-hover;
  }

  &:focus {
    @apply border-hover;
  }
}

@mixin button-secondary {
  @apply base-button bg-transparent text-primary;
  @apply border-primary;

  &:hover,
  &:focus {
    @apply bg-layer-4;
